DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.food_items f JOIN ciqual_reference r ON r.name=f.name
             WHERE f.source='ANSES' GROUP BY f.name HAVING count(*)>1) THEN
    RAISE EXCEPTION 'Duplicate ANSES names: review before importing';
  END IF;
END $$;
UPDATE public.food_items f SET ciqual_code=r.code, source_version='2025',
 source_url='https://doi.org/10.57745/RDMHWY', source_license='Etalab-2.0', nutrients_raw=r.raw
FROM ciqual_reference r WHERE f.source='ANSES' AND f.name=r.name;
UPDATE public.food_items SET energy_kcal=CASE
 WHEN replace(trim(nutrients_raw->>'energy_kcal'), ',', '.') ~ '^[0-9]+(\.[0-9]+)?$' THEN (replace(trim(nutrients_raw->>'energy_kcal'), ',', '.'))::double precision
 WHEN replace(trim(nutrients_raw->>'energy_kcal'), ',', '.') ~ '^< *[0-9]+(\.[0-9]+)?$' THEN trim(replace(replace(trim(nutrients_raw->>'energy_kcal'), ',', '.'),'<',''))::double precision
 WHEN lower(replace(trim(nutrients_raw->>'energy_kcal'), ',', '.'))='traces' THEN 0
 ELSE NULL END
WHERE source='ANSES' AND source_version='2025' AND ciqual_code IS NOT NULL;
UPDATE public.food_items SET proteins=CASE
 WHEN replace(trim(nutrients_raw->>'proteins'), ',', '.') ~ '^[0-9]+(\.[0-9]+)?$' THEN (replace(trim(nutrients_raw->>'proteins'), ',', '.'))::double precision
 WHEN replace(trim(nutrients_raw->>'proteins'), ',', '.') ~ '^< *[0-9]+(\.[0-9]+)?$' THEN trim(replace(replace(trim(nutrients_raw->>'proteins'), ',', '.'),'<',''))::double precision
 WHEN lower(replace(trim(nutrients_raw->>'proteins'), ',', '.'))='traces' THEN 0
 ELSE NULL END
WHERE source='ANSES' AND source_version='2025' AND ciqual_code IS NOT NULL;
UPDATE public.food_items SET carbohydrates=CASE
 WHEN replace(trim(nutrients_raw->>'carbohydrates'), ',', '.') ~ '^[0-9]+(\.[0-9]+)?$' THEN (replace(trim(nutrients_raw->>'carbohydrates'), ',', '.'))::double precision
 WHEN replace(trim(nutrients_raw->>'carbohydrates'), ',', '.') ~ '^< *[0-9]+(\.[0-9]+)?$' THEN trim(replace(replace(trim(nutrients_raw->>'carbohydrates'), ',', '.'),'<',''))::double precision
 WHEN lower(replace(trim(nutrients_raw->>'carbohydrates'), ',', '.'))='traces' THEN 0
 ELSE NULL END
WHERE source='ANSES' AND source_version='2025' AND ciqual_code IS NOT NULL;
UPDATE public.food_items SET fat=CASE
 WHEN replace(trim(nutrients_raw->>'fat'), ',', '.') ~ '^[0-9]+(\.[0-9]+)?$' THEN (replace(trim(nutrients_raw->>'fat'), ',', '.'))::double precision
 WHEN replace(trim(nutrients_raw->>'fat'), ',', '.') ~ '^< *[0-9]+(\.[0-9]+)?$' THEN trim(replace(replace(trim(nutrients_raw->>'fat'), ',', '.'),'<',''))::double precision
 WHEN lower(replace(trim(nutrients_raw->>'fat'), ',', '.'))='traces' THEN 0
 ELSE NULL END
WHERE source='ANSES' AND source_version='2025' AND ciqual_code IS NOT NULL;
UPDATE public.food_items SET source='unverified'
WHERE source='ANSES' AND NOT EXISTS (SELECT 1 FROM ciqual_reference r WHERE r.name=food_items.name);
CREATE OR REPLACE VIEW public.selectable_food_items WITH (security_invoker=true) AS
SELECT * FROM public.food_items
WHERE source IN ('ANSES','fitness','coach')
 AND energy_kcal IS NOT NULL AND proteins IS NOT NULL
 AND carbohydrates IS NOT NULL AND fat IS NOT NULL
 AND energy_kcal >= 0 AND proteins >= 0 AND carbohydrates >= 0 AND fat >= 0;
REVOKE ALL ON public.selectable_food_items FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.selectable_food_items TO anon, authenticated, service_role;
COMMENT ON VIEW public.selectable_food_items IS 'Complete nutrition references for new selections; inherits food_items RLS. Original incomplete rows remain in food_items.';
